import data from "./shapes.json";

export type Box = { cx: number; cy: number; w: number; h: number };
export type ShapeTile = { d: string; box: Box };
export type SpillShape = {
  pour: string;
  origin: [number, number];
  tiles: Record<string, ShapeTile>;
  sparks: string;
};
export type DialShape = {
  pour: string;
  clip: string;
  A: number[];
  cells: { id: string; d: string; box: Box; mid: number }[];
  sparks: string;
};

/** The approved shapes, generated by the reference scripts in the design docs. */
export const SHAPES = data as unknown as {
  sv: SpillShape;
  bl: SpillShape;
  ab: SpillShape;
  psv: SpillShape;
  pbl: SpillShape;
  pab: SpillShape;
  pf: DialShape;
  ppf: { pour: string };
};

export const STAGE = {
  desktop: { w: 1280, h: 800 },
  phone: { w: 390, h: 844 },
} as const;
